:root {
  --ink: #263238;
  --paper: #fffdf4;
  --coral: #ef765f;
  --mint: #cbe9d9;
  --line: #263238;
}

.table-marker {
  width: 380px;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 16px;
}

.marker-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--mint);
  border-bottom: 2px solid var(--line);
}

.marker-head h1 {
  margin: 0;
  color: var(--ink);
  font-size: 15px;
  font-weight: 800;
}

.status {
  padding: 4px 7px;
  color: var(--paper);
  background: var(--coral);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
}

.marker-body {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
}

.table-number {
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
  color: var(--paper);
  background: var(--ink);
  border-radius: 50%;
  font-size: 27px;
}

.marker-body p {
  margin: 0;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.45;
}

.marker-body b {
  font-size: 16px;
}

.marker-body span {
  color: var(--coral);
}
